import { defineConfig } from "vite";
import react from "@vitejs/plugin-react";
import path from "node:path";

const DEV_HOST = "127.0.0.1";
const DEV_PORT = 5173;

export default defineConfig({
  plugins: [react()],
  resolve: {
    alias: {
      "@": path.resolve(__dirname, "./src"),
    },
  },
  clearScreen: false,
  server: {
    host: DEV_HOST,
    port: DEV_PORT,
    strictPort: true,
    hmr: {
      protocol: "ws",
      host: DEV_HOST,
      clientPort: DEV_PORT,
    },
    watch: {
      usePolling: true,
      interval: 100,
      ignored: ["**/src-tauri/**", "**/target/**", "**/.git/**"],
    },
  },
});

import React from "react";
import ReactDOM from "react-dom/client";
import App from "./App";
import { installSettingsRuntimeBridge } from "./lib/settingsRuntimeBridge";
import { applyCachedTerminalBackground } from "./lib/terminalSettings";
import { RemoteApp } from "./remote/RemoteApp";
import "./index.css";
import "./settings-runtime.css";

installSettingsRuntimeBridge();
applyCachedTerminalBackground();

const isTauriApp = typeof window !== "undefined" && Boolean((window as any).__TAURI_INTERNALS__);

ReactDOM.createRoot(document.getElementById("root") as HTMLElement).render(
  <React.StrictMode>
    {isTauriApp ? <App /> : <RemoteApp />}
  </React.StrictMode>
);

if (typeof window !== "undefined" && "serviceWorker" in navigator && !isTauriApp) {
  window.addEventListener("load", () => {
    navigator.serviceWorker.register("/sw.js").catch(() => {});
  });
}

@font-face {
  font-family: "Geist";
  src: url("./assets/geist-variable.woff2") format("woff2");
  font-style: normal;
  font-weight: 100 900;
  font-display: swap;
}

@tailwind base;
@tailwind components;
@tailwind utilities;

:root {
  color-scheme: dark;

  --radius: 0.5rem;

  /* Ferryx brand tone: intentional divergence from Orca original (#0a0a0a) */
  --background: #23262d;
  --background-rgb: 35 38 45;
  --foreground: #fafafa;
  --foreground-rgb: 250 250 250;
  --card: #171717;
  --card-rgb: 23 23 23;
  --card-foreground: #fafafa;
  --card-foreground-rgb: 250 250 250;
  --popover: #171717;
  --popover-rgb: 23 23 23;
  --popover-foreground: #fafafa;
  --popover-foreground-rgb: 250 250 250;
  --primary: #e5e5e5;
  --primary-rgb: 229 229 229;
  --primary-foreground: #171717;
  --primary-foreground-rgb: 23 23 23;
  --secondary: #262626;
  --secondary-rgb: 38 38 38;
  --secondary-foreground: #fafafa;
  --secondary-foreground-rgb: 250 250 250;
  --muted: #262626;
  --muted-rgb: 38 38 38;
  --muted-foreground: #a1a1a1;
  --muted-foreground-rgb: 161 161 161;
  --accent: #404040;
  --accent-rgb: 64 64 64;
  --accent-foreground: #fafafa;
  --accent-foreground-rgb: 250 250 250;
  --destructive: #ff6568;
  --destructive-rgb: 255 101 104;
  --destructive-foreground: #0a0a0a;
  --destructive-foreground-rgb: 10 10 10;
  --border: #ffffff12;
  --border-rgb: 255 255 255;
  --border-alpha: 0.0706;
  --input: #ffffff26;
  --input-rgb: 255 255 255;
  --input-alpha: 0.149;
  --ring: #737373;
  --ring-rgb: 115 115 115;

  --sidebar: #23262d;
  --sidebar-rgb: 35 38 45;
  --sidebar-foreground: #fafafa;
  --sidebar-foreground-rgb: 250 250 250;
  --sidebar-primary: #1447e6;
  --sidebar-primary-rgb: 20 71 230;
  --sidebar-primary-foreground: #fafafa;
  --sidebar-primary-foreground-rgb: 250 250 250;
  --sidebar-accent: #262626;
  --sidebar-accent-rgb: 38 38 38;
  --sidebar-accent-foreground: #fafafa;
  --sidebar-accent-foreground-rgb: 250 250 250;
  --sidebar-border: #ffffff12;
  --sidebar-border-rgb: 255 255 255;
  --sidebar-border-alpha: 0.0706;
  --sidebar-ring: #525252;
  --sidebar-ring-rgb: 82 82 82;

  --worktree-sidebar: #23262d;
  --worktree-sidebar-rgb: 35 38 45;
  --worktree-sidebar-foreground: #fafafa;
  --worktree-sidebar-foreground-rgb: 250 250 250;
  --worktree-sidebar-accent: #404040;
  --worktree-sidebar-accent-rgb: 64 64 64;
  --worktree-sidebar-accent-foreground: #fafafa;
  --worktree-sidebar-accent-foreground-rgb: 250 250 250;
  --worktree-sidebar-border: #ffffff12;
  --worktree-sidebar-border-rgb: 255 255 255;
  --worktree-sidebar-border-alpha: 0.0706;
  --worktree-sidebar-ring: #737373;
  --worktree-sidebar-ring-rgb: 115 115 115;

  --terminal: #282c34;
  --terminal-rgb: 40 44 52;
  --status-working: #60a5fa;
  --status-working-rgb: 96 165 250;
  --status-warning: #fbbf24;
  --status-warning-rgb: 251 191 36;
  --status-success: #86efac;
  --status-success-rgb: 134 239 172;
  --status-idle: #737373;
  --status-idle-rgb: 115 115 115;
}

html,
body,
#root {
  min-height: 100%;
  height: 100%;
}

body {
  margin: 0;
  min-height: 100vh;
  background: var(--background);
  color: var(--foreground);
  font-family: "Geist", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  user-select: none;
  -webkit-user-select: none;
}

@layer utilities {
  .drag-region {
    -webkit-app-region: drag;
  }

  .no-drag {
    -webkit-app-region: no-drag;
  }

  .scrollbar-none {
    scrollbar-width: none;
  }

  .scrollbar-none::-webkit-scrollbar {
    display: none;
  }

  .scrollbar-sleek {
    scrollbar-color: rgb(var(--muted-foreground-rgb) / 0.28) transparent;
    scrollbar-width: thin;
  }

  .scrollbar-sleek::-webkit-scrollbar {
    width: 6px;
    height: 6px;
  }

  .scrollbar-sleek::-webkit-scrollbar-thumb {
    border-radius: 999px;
    background: rgb(var(--muted-foreground-rgb) / 0.28);
  }

  .terminal-host {
    position: relative;
    min-width: 0;
    min-height: 0;
  }
}

import { existsSync } from "node:fs";
import { resolve } from "node:path";
import { describe, expect, it } from "vitest";

describe("ferryx app icon", () => {
  it("ships the authentic master dark metallic squircle icon", () => {
    const pngPath = resolve(process.cwd(), "src/assets/ferryx-icon.png");
    expect(existsSync(pngPath)).toBe(true);
  });
});

// @vitest-environment node

import { describe, expect, it } from "vitest";
import type { UserConfig } from "vite";

describe("Tauri Vite HMR configuration", () => {
  it("uses one deterministic IPv4 loopback endpoint and polling file watching", async () => {
    const configPath = "../../vite.config";
    const configModule = await import(/* @vite-ignore */ configPath);
    const config = configModule.default as UserConfig;

    expect(config.server?.host).toBe("127.0.0.1");
    expect(config.server?.port).toBe(5173);
    expect(config.server?.strictPort).toBe(true);
    expect(config.server?.hmr).toMatchObject({
      protocol: "ws",
      host: "127.0.0.1",
      clientPort: 5173,
    });
    expect(config.server?.watch).toMatchObject({
      usePolling: true,
      interval: 100,
    });
  });
});
